# Read input
import sys

def get_divisors(n):
    """Return all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total = sum(a)
    min_total = total

    # Try all possible pairs (i, j) with i != j
    for i in range(n):
        for j in range(n):
            if i == j:
                continue

            # For each possible divisor x of a[i]
            for x in get_divisors(a[i]):
                new_i = a[i] // x
                new_j = a[j] * x
                # Check if all values stay positive
                if new_i > 0 and new_j > 0:
                    new_total = total - a[i] + new_i - a[j] + new_j
                    if new_total < min_total:
                        min_total = new_total

    print(min_total)

if __name__ == "__main__":
    main()
"}

