import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    chef_dict = {}
    chef_votes = {}

    for _ in range(N):
        name = next(it)
        country = next(it)
        chef_dict[name] = country
        chef_votes[name] = 0

    for _ in range(M):
        name = next(it)
        chef_votes[name] += 1

    # Find country with most votes
    country_votes = {}
    for name, country in chef_dict.items():
        country_votes[country] = country_votes.get(country, 0) + chef_votes[name]

    if len(country_votes) == 1:
        country_winner = next(iter(country_votes.keys()))
    else:
        # Find lexicographically smallest country with max votes
        max_votes = max(country_votes.values())
        candidates = [country for country, votes in country_votes.items() if votes == max_votes]
        country_winner = min(candidates)

    # Find chef with most votes
    if len(chef_votes) == 1:
        chef_winner = next(iter(chef_votes.keys()))
    else:
        # Find lexicographically smallest chef with max votes
        max_votes = max(chef_votes.values())
        candidates = [name for name, votes in chef_votes.items() if votes == max_votes]
        chef_winner = min(candidates)

    print(country_winner)
    print(chef_winner)

if __name__ == "__main__":
    solve()
"}

