def card_value(card):
    if card == 1:
        return 1, 11
    elif 2 <= card <= 9:
        return card, card
    elif 10 <= card <= 13:
        return 10, 10


def max_hand_score(cards):

    # Try all combinations
    max_score = 0

    # Create a list of possible values for each card
    possible_values = [card_value(card) for card in cards]

    # Use backtracking to find the maximum score
    def backtrack(index, current_score):
        nonlocal max_score

        # Base case: we've used all cards
        if index == len(cards):
            max_score = max(max_score, current_score)
            return

        # Try both values for this card (or only one if it's not 1)
        for val in possible_values[index]:
            if current_score + val <= 21:
                backtrack(index + 1, current_score + val)

    backtrack(0, 0)
    return max_score if max_score <= 21 else 0


def main():
    lines = []

    # Read all input lines
    for line in iter(input, ''):
        lines.append(line.strip())

    # Process each dataset
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            i += 1
            continue

        # Check if we've reached the end
        if line == '0':
            break

        # Parse cards
        cards = list(map(int, line.split()))

        # Calculate score
        score = max_hand_score(cards)

        # Output result
        print(score)
        i += 1

if __name__ == '__main__':
    main()
"}

