def solve(n):
    if n % 4 == 0:
        return '4' * (n // 4)
    if n % 7 == 0:
        return '7' * (n // 7)

    min_len = float('inf')
    best_x = 0
    best_y = 0

    # Try all possible numbers of 4s from 0 to n//4
    max_4s = n // 4

    for x in range(max_4s + 1):
        remaining = n - 4 * x
        if remaining >= 0 and remaining % 7 == 0:
            y = remaining // 7
            total_digits = x + y

            if total_digits < min_len:
                min_len = total_digits
                best_x = x
                best_y = y
            elif total_digits == min_len:
                # Among equal length, we want more 4s earlier
                # '4'*x + '7'*y is lexicographically smallest
                if x > best_x:
                    best_x = x
                    best_y = y

    if best_x == 0 and best_y == 0:
        return '-1'
    else:
        return '4' * best_x + '7' * best_y

