def solve():
    n = int(sys.stdin.readline())
    rectangles = []

    for _ in range(n):
        x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
        rectangles.append((x1, y1, x2, y2))

    # Try different parity-based coloring strategies

    # Strategy 1: (x1 % 2, y1 % 2) -> 4 colors
    colors1 = []
    for rect in rectangles:
        color = 1 + (rect[0] % 2) + 2 * (rect[1] % 2)
        colors1.append(color)

    # Strategy 2: (x1 % 2, y2 % 2) -> 4 colors
    colors2 = []
    for rect in rectangles:
        color = 1 + (rect[0] % 2) + 2 * (rect[3] % 2)
        colors2.append(color)

    # Strategy 3: (x2 % 2, y1 % 2) -> 4 colors
    colors3 = []
    for rect in rectangles:
        color = 1 + (rect[2] % 2) + 2 * (rect[1] % 2)
        colors3.append(color)

    # Strategy 4: (x2 % 2, y2 % 2) -> 4 colors
    colors4 = []
    for rect in rectangles:
        color = 1 + (rect[2] % 2) + 2 * (rect[3] % 2)
        colors4.append(color)

    # Check which strategy works (all pairs of rectangles that touch by sides should have different colors)

    def is_valid(colors):
        for i in range(n):
            for j in range(n):
                # Check if rectangles i and j touch by sides
                # Check vertical sides (left/right)
                if abs(rectangles[i][0] - rectangles[j][2]) == 0:
                    if colors[i] == colors[j]:
                        return False
                elif abs(rectangles[i][2] - rectangles[j][0]) == 0:
                    if colors[i] == colors[j]:
                        return False
                # Check horizontal sides (bottom/top)
                elif abs(rectangles[i][1] - rectangles[j][3]) == 0:
                    if colors[i] == colors[j]:
                        return False
                elif abs(rectangles[i][3] - rectangles[j][1]) == 0:
                    if colors[i] == colors[j]:
                        return False
        return True

    # Since n can be up to 500,000, checking all pairs is O(n^2) and might be slow
    # But let's just try all 4 strategies and pick the first valid one

    for colors in [colors1, colors2, colors3, colors4]:
        if is_valid(colors):
            print("YES")
            for color in colors:
                print(color)
            return

    # If none work, return NO
    print("NO")

