def calculate_score(elements):
    """Recursively calculate the maximum score for a group of elements"""
    if len(elements) == 1:
        return sum(elements)

    max_score = 0

    # Try all possible ways to split the multiset into two non-empty groups
    for i in range(1, len(elements)):
        # Take first i elements for one group, remaining for the other
        group1 = elements[:i]
        group2 = elements[i:]

        score = sum(elements) + calculate_score(group1) + calculate_score(group2)

        if score > max_score:
            max_score = score

    return max_score

def solve():
    n = int(input())
    a = list(map(int, input().split()))

