def get_divisors(n):
    """Get all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    total = sum(a)

    # Try all pairs of machines
    min_total = total

    # Get all divisors for each machine
    divisors_list = []
    for num in a:
        divisors_list.append(get_divisors(num))

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # For machine i, try all its divisors as x
            a_i = a[i]
            a_j = a[j]

            # For each possible x
            for x in divisors_list[i]:
                # Compute new total
                new_total = total - a_i + (a_i // x) + a_j * x
                if new_total < min_total:
                    min_total = new_total

    print(min_total)

solve()
