def solve():
    N = int(input())

    # Build the tree
    from collections import defaultdict
    tree = defaultdict(list)
    edges = []

    for _ in range(N - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)
        edges.append((a, b))

    # Function to compute distances from each vertex
    def compute_distances():
        distances = [[-1] * (N + 1) for _ in range(N + 1)]  # distances[i][j] = distance between i and j

        def bfs(start):
            q = [start]
