    # Output simple multiplication: a*3
    common_count = counts[0]
    letter = next(iter(letter_counts.keys()))  # get first letter
    length = 1 + 1 + len(str(common_count))  # a*3 -> 3 characters
    print(length)
else:
    # Output sum of terms: a*3+2*b
    length = 0
    for c in letter_counts:
        count = letter_counts[c]
        length += 1 + 1 + len(str(count))
    print(length)
