    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = []

    for _ in range(t):
        n = int(data[idx])
        k = int(data[idx+1])
        idx += 2

        # Find the minimum number of packages
        min_packages = float('inf')

        for i in range(1, k + 1):
            # Calculate number of packages needed for package size i
            if i > n:
                # We need 1 package of size i (which is > n, so not useful)
                packages = 1
            else:
                # We need ceil(n / i) packages
                packages = (n + i - 1) // i  # This is integer ceiling

            if packages < min_packages:
                min_packages = packages

        out_lines.append(str(min_packages))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
