import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = []

    for _ in range(t):
        n = int(data[idx])
        k = int(data[idx+1])
        idx += 2

        if k >= n:
            out_lines.append(str(1))
            continue

        # Find the largest divisor of n that is <= k
        # Check from min(k, n-1) down to 1
        # But we don't need to check all of them, just up to sqrt(n)
        limit = min(k, n-1)
        sqrt_n = int(n ** 0.5)

        # Check from limit down to 1, but stop at sqrt_n
        found = False
        for i in range(limit, sqrt_n, -1):
            if n % i == 0:
                out_lines.append(str(n // i))
                found = True
                break

        if not found:
            # Check from 1 to sqrt_n to see if any divisor has complement <= k
            for i in range(1, sqrt_n + 1):
                if n % i == 0:
                    if n // i <= k:
                        out_lines.append(str(n // i))
                        found = True
                        break

        if not found:
            out_lines.append(str(n))  # Use package size 1, need n packages

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
