from collections import deque

def bfs(u, v, edges, n):
    """
    Check if there's a path from u to v using the given edges
    """
    visited = [False] * n
    queue = deque([u])
    visited[u] = True

    while queue:
        node = queue.popleft()

        if node == v:
            return True

        for neighbor in edges:
            # Find if there's an edge from node to neighbor
            for a, b in edges:
                if (a == node and b == neighbor) or (a == neighbor and b == node):
                    break
            else:
                continue

            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return False

for _ in range(k):
