def solve():
    tc = int(input())

    for _ in range(tc):
        url = input().strip()

        # Calculate original length
        original_length = len(url)

        # Calculate remaining length after removing vowels and the prefixes/suffixes
        jhools_length = 0

        # Skip "www." at start
