def solve_test_case(N, K, nums):
    min_operations = float('inf')

    # Try making all values into multiples of various divisors of K
    for d in range(1, K + 1):
        if K % d == 0:
            # Convert each value to the nearest multiple of d
            operations = 0
            for x in nums:
                remainder = x % d
                ops = min(remainder, d - remainder)
                operations += ops
            min_operations = min(min_operations, operations)

