def calculate_hand_score(cards):

    # Count occurrences of each card
    count = [0] * 14
    for card in cards:
        count[card] += 1

    # We need to choose values for 1s that maximize the score
    # 1 can be either 1 or 11

    # Strategy: Try all combinations of choosing 1s to be 11
    # Since there are at most 100 cards, we can do this with a simple loop

    # Base value: 1 is 1 point, all other cards are their actual value
    score = 0
    one_count = 0
    for i in range(1, 14):
        if i == 1:
            score += 1
        elif 2 <= i <= 9:
            score += i
        elif 10 <= i <= 13:
            score += 10

    one_count = count[1]

    # Try each card from 1 to 13
    for i in range(1, 14):
        if i == 1:
            continue  # We already counted all 1s in the base value

        if 2 <= i <= 9:
            score += (i - 1)
        elif 10 <= i <= 13:
            score += 0


    best_score = score

    # Now try to convert 1s from 1 to 11
    # This gives +10 for each 1 we convert
    # But if score exceeds 21, we set to 0

    # Try each 1 that we might convert
    for i in range(one_count + 1):
        new_score = score + 10 * i
        if new_score > 21:
            new_score = 0
        best_score = max(best_score, new_score)

    return best_score

