def gcd_list(arr):
    result = arr[0]
    for num in arr[1:]:
        result = math.gcd(result, num)
        if result == 1:
            break
    return result

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
