def kadane(arr):
    n = len(arr)
    max_current = max_global = arr[0]
    for i in range(1, n):
        max_current = max(arr[i], max_current + arr[i])
        max_global = max(max_global, max_current)
    return max_global

n = int(input())
mat = []
for _ in range(n):
    mat.append(list(map(int, input().split())))

max_sum = -float('inf')

for t in range(n):
    prefix = [0] * n
    for b in range(t, n):
        for j in range(n):
            prefix[j] += mat[b][j]
        current = prefix[0]
        best = prefix[0]
        for i in range(1, n):
            current = max(prefix[i], current + prefix[i])
            best = max(best, current)
        max_sum = max(max_sum, best)

print(max_sum)
"}

