import sys
from collections import Counter

def is_divisible_by_60(y):
    digit_count = Counter(y)

    # Need at least one '0'
    if digit_count.get('0', 0) == 0:
        return False

    # Sum of digits must be divisible by 3
    if sum(int(d) for d in y) % 3 != 0:
        return False

    # For divisibility by 4, last two digits must form a number divisible by 4
    # If we have at least two '0's, we can put one at the end and use another as the last digit
    if digit_count['0'] >= 2:
        return True

    # For single '0', we need at least one even digit for the second last position
    # And if we only have two digits total, both must be '0'
    if digit_count['0'] == 1:
        if len(y) == 2:
            return y[0] == '0'
        # We need at least one other even digit
        return any(int(d) % 2 == 0 for d in y if d != '0')

    return False

def solve() -> None:
    n = int(sys.stdin.readline())
    for _ in range(n):
        y = sys.stdin.readline().strip()
        if is_divisible_by_60(y):
            print("red")
        else:
            print("cyan")

if __name__ == "__main__":
    solve()
"}

