def compare_names(name1, name2):
    """Find the first position where name1 and name2 differ. Return (index, char1, char2) if they differ, else (None, None, None)"""
    for i in range(min(len(name1), len(name2))):
        if name1[i] != name2[i]:
            return (i, name1[i], name2[i])
    # If all compared characters are equal, the shorter one comes first
    return (None, None, None)

def solve():
    n = int(input())
    names = [input().strip() for _ in range(n)]

    # Build a graph of character order constraints
    graph = {c: [] for c in "abcdefghijklmnopqrstuvwxyz"}
    # Also track which characters have constraints
    has_constraint = {c: False for c in "abcdefghijklmnopqrstuvwxyz"}

    for i in range(n - 1):
        name1, name2 = names[i], names[i + 1]
        index, char1, char2 = compare_names(name1, name2)

        if index is None:
            # name1 is a prefix of name2 (or vice versa, name2 is a prefix of name1?)
            # If name1 is a prefix of name2, name1 should come first - this is fine
