n, m = map(int, input().split())
p = input().strip()

if m > 0:
    y = list(map(int, input().split()))
else:
    y = []

l = len(p)

# Create an array to store required characters for each position
chars = {}  # key: position (0-indexed), value: list of required characters

# Process each constraint
for i, yi in enumerate(y):
    start = yi - 1  # convert to 0-indexed
    end = yi + l - 2  # convert to 0-indexed

    # Check for conflicts before updating
    for j in range(start, end + 1):
        if j in chars:
            if p[j - start] != chars[j][0]:
                print(0)
                exit()
        else:
            chars[j] = [p[j - start]]

    # Update the characters in the constraint range
    for j in range(start, end + 1):
        chars[j] = [p[j - start]]

# Count free positions
free = 0
for i in range(n):
    if i not in chars:
        free += 1

# Answer = 26^free mod 1000000007
result = pow(26, free, 1000000007)
print(result)
