    s = input().strip()
    digits = list(s)
    num_digits = len(digits)

    # Check if we can form a number divisible by 20
    # We need at least one zero
    if '0' not in digits:
        print("cyan")
        continue

    # For "00": need at least two zeros
    # For "20", "40", "60", "80": need one of {2,4,6,8} and at least one zero
    # And we need at least two digits total

    # Check if we have at least two zeros
    if digits.count('0') >= 2:
        print("red")
    # Check if we have at least one of {2,4,6,8} and at least one zero
    elif digits.count('2') > 0 or digits.count('4') > 0 or digits.count('6') > 0 or digits.count('8') > 0:
        # We need to check if we can form a number with these properties
        # We have at least one zero, and we need one of {2,4,6,8}
        # And we need at least one more digit for the rest of the number
        # Actually, if we have two digits, we can just check if they form one of {20, 40, 60, 80}
        if num_digits == 2:
            if s in {"20", "40", "60", "80"}:
                print("red")
            else:
                print("cyan")
        else:
            # For numbers with more than 2 digits, we just need at least one zero
            # Because we can always rearrange to put one of {2,4,6,8} at the second to last position
            # and a zero at the last position
            print("red")
    else:
        print("cyan")

