{"code": "t = int(input())
for _ in range(t):
    s = input().strip()

    # Count character frequencies
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find maximum frequency
    max_freq = max(freq.values())

    # Find all characters with max frequency
    candidates = [char for char, count in freq.items() if count == max_freq]

    # Choose character with lowest ASCII value
    replace_char = min(candidates)

    # Replace character with '?', but we need to ensure we replace all occurrences
    result = ''
    for char in s:
        if char == replace_char:
            result += '?'
        else:
            result += char

    print(result)
"}

