# We need to find non-negative integers a and b such that 4a + 7b = n
# and then find the minimum number formed by a 4's and b 7's

# First, check if n is divisible by 4 or 7 directly
if n % 4 == 0:
    print('4' * (n // 4))
    exit()
if n % 7 == 0:
    print('7' * (n // 7))
    exit()

# Try all combinations of b (number of 7s) from 0 to n//7
min_number = None

for b in range(0, n // 7 + 1):
    if (n - 7 * b) % 4 == 0:
        a = (n - 7 * b) // 4
        # Create the number with a 4's and b 7's
        candidate = '4' * a + '7' * b
        if min_number is None or candidate < min_number:
            min_number = candidate

if min_number is not None:
    print(min_number)
else:
    print(-1)
"}

