import sys

def odd_part(n):
    """Return the odd part of n (i.e., n with all factors of 2 removed)."""
    while n % 2 == 0:
        n //= 2
    return n

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    heights = list(map(int, data[1:1+n]))
    # compute odd parts
    parts = [odd_part(h) for h in heights]
    if all(p == parts[0] for p in parts):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

