# The problem is to find the maximum sum submatrix that is contiguous in both directions
# This is essentially the 2D version of Kadane's algorithm

# First, create a prefix sum matrix to quickly compute submatrix sums
prefix = [[0] * (n + 1) for _ in range(n + 1)]
for i in range(n):
    for j in range(n):
        prefix[i+1][j+1] = matrix[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

max_sum = float('-inf')

# Check all submatrices of various row and column spans
for height in range(1, n + 1):
    for width in range(1, n + 1):
        # This is O(n^2) time, but since n <= 100, it's okay
        for row_start in range(n - height + 1):
            for col_start in range(n - width + 1):
                # Calculate the sum of submatrix starting at (row_start, col_start)
                # of height `height` and width `width`
                row_end = row_start + height
                col_end = col_start + width
                sum_val = prefix[row_end][col_end] - prefix[row_start][col_end] - \n                          prefix[row_end][col_start] + prefix[row_start][col_start]

                if sum_val > max_sum:
                    max_sum = sum_val

print(max_sum)
