import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    leaders = list(map(int, data[2:2+m]))

    if m == 1:
        print(' '.join(str(i) for i in range(1, n+1)))
        return

    # For steps 1 to m-1, we have constraints
    a = [0] * n
    constraints = {}
    for i in range(m-1):
        current = leaders[i]
        next_leader = leaders[i+1]

        # We have a constraint: a[current-1] = (next_leader - current) % n
        constraints[current-1] = (next_leader - current) % n

    # Check if the constraints are consistent
    for pos, val in constraints.items():
        if a[pos] != 0 and a[pos] != val:
            print(-1)
            return

    # Fill in the constraints
    for pos, val in constraints.items():
        a[pos] = val

    # Check if the partially filled values are consistent
    used = [False] * n
    valid = True
    for i in range(n):
        if a[i] == 0:
            continue
        if 1 <= a[i] <= n and not used[a[i]-1]:
            used[a[i]-1] = True
        else:
            valid = False
            break

    if not valid:
        print(-1)
        return

    # Check if the constraints produce the expected leaders
    valid_leader = True
    current = leaders[0]
    for i in range(1, m):
        expected = leaders[i]
        actual = (current - 1 + a[current-1]) % n + 1
        if actual != expected:
            valid_leader = False
            break
        current = expected

    if not valid_leader:
        print(-1)
        return

    # Fill in the remaining positions
    remaining = []
    for i in range(n):
        if a[i] == 0:
            remaining.append(i)

    remaining_vals = [i for i in range(1, n+1) if not used[i-1]]

    # Fill remaining positions with remaining values in any order
    for pos, val in zip(remaining, remaining_vals):
        a[pos] = val

    print(' '.join(str(val) for val in a))

if __name__ == '__main__':
    solve()
