        return False

    # Check if the remaining prefix can be decomposed
    prefix = word[:suffix_start]
    return decompose(word, prefix, suffix, suffix_start)

def decompose(word, prefix, candidate_suffix, suffix_start):
    """Check if we can decompose the word from this point."
    n = len(word)

    # Base case: we've reached the end of the word
    if prefix == word:
        return True

    # Try all possible suffixes of length 2 or 3
    for i in range(1, 4):
        if suffix_start + i > n:
            continue
        candidate = word[suffix_start: suffix_start + i]

        # Skip the same suffix consecutively
        if candidate == candidate_suffix and i == len(candidate_suffix):
            continue

        # Recursively decompose with this suffix
        if decompose(word, prefix + candidate, candidate, suffix_start + i):
            return True

    return False

def solve(s):
    n = len(s)

    # The root must be more than 4 letters, so we need at least 2 letters for suffixes
    if n < 7:
        return []

    # Try all possible suffixes of length 2 or 3 at each position
    valid_suffixes = set()

    for pos in range(n - 1, 3, -1):
        for length in [2, 3]:
            if pos + length > n:
                continue
            suffix = s[pos - length:pos]

            # Check if this suffix is valid
            if is_valid_suffix(s, suffix, pos - length):
                valid_suffixes.add(suffix)

    return sorted(valid_suffixes)

s = input().strip()
result = solve(s)

print(len(result))
for suffix in result:
    print(suffix)

