def is_winning(d_x, d_y, memo):
    if (d_x, d_y) in memo:
        return memo[(d_x, d_y)]

    # Check if we've reached the target (both distances are 0)
    if d_x == 0 and d_y == 0:
        return False  # Not a valid position, game already ended

    # Try all possible moves
    for k in range(1, d_x + 1):
        if not is_winning(d_x - k, d_y, memo):
            memo[(d_x, d_y)] = True
            return True

    for k in range(1, d_y + 1):
        if not is_winning(d_x, d_y - k, memo):
            memo[(d_x, d_y)] = True
            return True

    for k in range(1, min(d_x, d_y) + 1):
        if not is_winning(d_x - k, d_y - k, memo):
            memo[(d_x, d_y)] = True
            return True

    # No winning moves
    memo[(d_x, d_y)] = False
    return False

# Precompute all positions up to max size
