    # For any k in 1..d_x, (d_x-k, d_y) should be winning
    for k in range(1, d_x + 1):
        if not is_winning(d_x - k, d_y):
            return True

    # For any k in 1..d_y, (d_x, d_y-k) should be winning
    for k in range(1, d_y + 1):
        if not is_winning(d_x, d_y - k):
            return True

    # For any k in 1..min(d_x, d_y), (d_x-k, d_y-k) should be winning
    for k in range(1, min(d_x, d_y) + 1):
        if not is_winning(d_x - k, d_y - k):
            return True

    # No winning moves - this is a losing position
    return False

