    n, k = map(int, input().split())
    # Find the largest divisor of n that is <= k
    if k >= n:
        print(1)  # n divides itself
    else:
        # Find the largest divisor of n that is <= k
        # Start from the smallest divisor > k and go down
        # But how to efficiently find this?
        # For large numbers (up to 10^9), we need an efficient approach
        answer = n
        # Check if n has any divisors <= k
        # One approach: iterate from 1 to sqrt(n) and check divisibility
        max_div = 1
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                if i <= k:
                    max_div = i
                if n // i <= k:
                    max_div = n // i
        print(n // max_div)
