import sys

# Read input
data = sys.stdin.read().split()
if not data:
    sys.exit()
idx = 0
n = int(data[idx]); idx += 1
rects = []
for _ in range(n):
    x1, y1, x2, y2 = int(data[idx]), int(data[idx+1]), int(data[idx+2]), int(data[idx+3])
    idx += 4
    rects.append((x1, y1, x2, y2))

# Build adjacency list: if two rectangles touch by side, add edge
# Rectangles (x1,y1,x2,y2) and (x1',y1',x2',y2')
def touch(r1, r2):
    x1a, y1a, x2a, y2a = r1
    x1b, y1b, x2b, y2b = r2
    # Check if sides touch
    if x1a == x2b and y1a < y2b and y1b < y2a:
        return True
    if x2a == x1b and y1a < y2b and y1b < y2a:
        return True
    if y1a == y2b and x1a < x2b and x1b < x2a:
        return True
    if y2a == y1b and x1a < x2b and x1b < x2a:
        return True
    return False

adj = [[] for _ in range(n)]
for i in range(n):
    for j in range(i+1, n):
        if touch(rects[i], rects[j]):
            adj[i].append(j)

# BFS color
# Use colors 1..4
color = [-1]*n
color[0] = 1
from collections import deque
q = deque()
q.append(0)
while q:
    u = q.popleft()
    for v in adj[u]:
        if color[v] == -1:
            used = set()
            for w in adj[v]:
                if color[w] != -1:
                    used.add(color[w])
            for c in range(1, 5):
                if c not in used:
                    color[v] = c
                    q.append(v)
                    break
        # else already colored

# Output
print("YES")
for c in color:
    print(c)

