for _ in range(t):
    # Skip empty line (if any)
    while True:
        line = input().strip()
        if line == "":
            continue
        elif line.isdigit():
            break
        else:
            raise ValueError("Unexpected input format")

    n, m = map(int, line.split())

    # Count blocked cells in each column
    blocked = [0] * (n + 1)  # 1-indexed
    for i in range(1, m + 1):
        r, c = map(int, input().split())
        blocked[c] += 1

    # Check if we can tile
    if n % 2 == 0:
        # For even n, we just need an even number of unblocked cells
        if (2 * n - m) % 2 == 0:
            print("YES")
        else:
            print("NO")
    else:
        # For odd n, we need to be careful
        if m % 2 == 0 and (2 * n - m) % 2 == 0:
            # Check for forbidden patterns
            # Can't have both (1,c) and (2,c) blocked for the same c
            # Can't have both (1,c) and (2,c+1) blocked for the same c
            is_valid = True
            for c in range(1, n + 1):
                if blocked[c] >= 2:
                    is_valid = False
                    break
                # Check right neighbor
                if c + 1 <= n and blocked[c] == 1 and blocked[c + 1] == 1:
                    is_valid = False
                    break
            if is_valid:
                print("YES")
            else:
                print("NO")
        else:
            print("NO")
