def solve():
    n, m, k = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]

    # Find starting and target positions
    start = None
    target = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    if not start or not target:
        print(-1)
        return

    # BFS state: (row, col, visited_types, path)
    from collections import deque

    # Dictionary: (row, col, visited_types) -> shortest path length, lexicographically minimal path
    visited = {}

    # Start from 'S' with empty path
    queue = deque([(start[0], start[1], 0, "")])

    while queue:
        r, c, types_mask, path = queue.popleft()

        # Check if we reached 'T'
        if (r, c) == target:
            print(path)
            return

        # Try all four directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                new_types_mask = types_mask
                new_path = path

                cell = grid[nr][nc]

                # Don't revisit 'S'
                if cell == 'S':
                    continue

                # Check if we can visit this cell
                if cell == 'T':
                    # T is the endpoint, we'll handle it separately
                    pass
                else:
                    # cell is a lowercase letter
                    bit = ord(cell) - ord('a')

                    # Already visited this type, can pass through
                    if types_mask & (1 << bit):
                        pass
                    else:
                        # Check type limit
                        if types_mask.bit_count() >= k:
                            continue
                        new_types_mask |= (1 << bit)
                        new_path += cell

                # Handle T as a special case
                if cell == 'T':
                    # We need to end at T exactly once
                    pass

                key = (nr, nc, new_types_mask)

                # If not visited or found shorter path
                if key not in visited or len(path) + 1 < visited[key][0]:
                    visited[key] = (len(path) + 1, path + cell if cell != 'T' else path)
                    queue.append((nr, nc, new_types_mask, path + cell if cell != 'T' else path))

                # If same length, keep lexicographically smaller path
                elif len(path) + 1 == visited[key][0]:
                    existing_path = visited[key][1]
                    new_path_with_t = new_path + cell if cell != 'T' else new_path

                    if new_path_with_t < existing_path:
                        visited[key] = (len(path) + 1, new_path_with_t)
                        queue.append((nr, nc, new_types_mask, new_path_with_t))

    print(-1)

solve()
