import sys
from collections import Counter

def solve():
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    out_lines = []
    for i in range(1, n + 1):
        num = data[i].strip()
        digits = list(num)
        total = sum(int(c) for c in digits)
        m = len(digits)
        freq = Counter(digits)

        if m == 2:
            # check if this 2-digit number is divisible by 20 and sum of digits ≡ total
            if digits[0] + digits[1] in {"00", "20", "40", "60", "80"}:
                out_lines.append("red")
            else:
                out_lines.append("cyan")
        else:
            # try each valid ending pair
            valid_ending = {"00", "20", "40", "60", "80"}
            found = False
            for end in valid_ending:
                # check if we have enough digits to form end
                # end is a string of two characters
                if end[0] == end[1]:  # like "00"
                    if freq[end[0]] >= 2:
                        sum_two = int(end[0]) * 2
                        if (sum_two - total) % 3 == 0:
                            found = True
                            break
                else:
                    if freq[end[0]] >= 1 and freq[end[1]] >= 1:
                        sum_two = int(end[0]) + int(end[1])
                        if (sum_two - total) % 3 == 0:
                            found = True
                            break
            if found:
                out_lines.append("red")
            else:
                out_lines.append("cyan")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
