def solve():
    n, a, b, k, f = map(int, input().split())

    # Read trips
    trips = []
    for _ in range(n):
        s, e = input().split()
        trips.append((s, e))

    # Calculate cost of each trip
    costs = []
    prev_end = None

    for i in range(n):
        s, e = trips[i]
        if i == 0:
            # First trip, no transshipment
            cost = a
        elif prev_end == s:
            # Transshipment
            cost = b
        else:
            # Regular trip
            cost = a
        costs.append(cost)
        prev_end = e

    total = sum(costs)

    # Calculate cost savings for each unique route
    route_costs = {}
    routes_considered = set()

    for i in range(n):
        s, e = trips[i]
        # Consider route in both directions
        for route in [(s, e), (e, s)]:
            if route not in routes_considered:
                routes_considered.add(route)
                if route not in route_costs:
                    route_costs[route] = 0
                route_costs[route] += costs[i]

    # Now decide which routes to buy cards for
    # We only need to consider each route once, not both directions
    # Let's just keep routes where s < e lexicographically

    items = []
    for route, cost in route_costs.items():
        if route[0] < route[1]:
            # We only consider one direction
            items.append((f - cost, cost))

    # Solve knapsack: max capacity = k, max value = max savings
    # But we want to minimize cost, so we want to maximize total savings

    dp = [0] * (k + 1)

    for value, cost in items:
        for cap in range(k, -1, -1):
            if cost <= cap:
                dp[cap] = max(dp[cap], dp[cap - cost] + value)

    max_savings = max(dp)

    print(total - max_savings)

