    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    # BFS to find shortest path with constraints
    # State: (row, col, visited_types_set)
    dist = defaultdict(lambda: float('inf'))
    prev = defaultdict(str)  # Track the best path to each state

    # Start with empty visited set
    queue = deque([(start[0], start[1], frozenset())])
    dist[(start[0], start[1], frozenset())] = 0
    prev[(start[0], start[1], frozenset())] = ''

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    while queue:
