            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                next_char = grid[nr][nc]

                if next_char == 'S':
                    # Already passed S, cannot revisit
                    continue
                elif next_char == 'T':
                    # Reached target, but we need to continue
                    new_state = (nr, nc, visited_set)
                    new_dist = current_dist + 1

                    if dist[new_state] > new_dist:
                        dist[new_state] = new_dist
                        prev[new_state] = prev[(r, c, visited_set)]
                        queue.append(new_state)
                    elif dist[new_state] == new_dist:
                        current_path = prev[(r, c, visited_set)]
                        stored_path = prev[new_state]

                        if current_path < stored_path:
                            prev[new_state] = current_path
                else:
                    # Lowercase letter
                    if next_char in visited_set:
                        next_visited = visited_set
                    else:
                        if len(visited_set) + 1 > k:
                            continue  # Exceeds k different types
                        next_visited = visited_set | frozenset([next_char])

                    new_state = (nr, nc, next_visited)
