import sys
from collections import defaultdict, deque

def parse_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None

    n = int(data[0])
    m = int(data[1])
    path = list(map(int, data[2:2+m+1]))

    return n, m, path

def build_graph(path):
    # Build adjacency list
    graph = defaultdict(list)
    for i in range(len(path)-1):
        u = path[i]
        v = path[i+1]
        if u != v:
            graph[u].append(v)
            graph[v].append(u)

    # Build adjacency matrix
    adj = [[0] * (n+1) for _ in range(n+1)]
    for u in graph:
        for v in graph[u]:
            adj[u][v] = 1

    # Build degree list
    degrees = [0] * (n+1)
    for u in graph:
        degrees[u] = len(graph[u])

    return adj, degrees

def has_eulerian_circuit(adj, degrees):
    # Check if all vertices have even degrees
    for v in range(1, n+1):
        if degrees[v] % 2 != 0:
            return False

    # Check if the graph is connected (excluding isolated vertices)
    visited = set()
    start = 1
    queue = deque([start])
    visited.add(start)

    while queue:
        node = queue.popleft()
        for neighbor in range(1, n+1):
            if adj[node][neighbor] and neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return True

def generate_eulerian_circuits(adj, degrees, start):
    # Generate all Eulerian circuits using Hierholzer's algorithm
    # and sort them lexicographically

    # Build adjacency lists
    graph = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in range(1, n+1):
            if adj[u][v] and u < v:
                graph[u].append(v)
                graph[v].append(u)

    # Use Hierholzer's algorithm to find all circuits
    # This is simplified and may not be complete

    # Convert to simple adjacency list
    adj_list = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in range(1, n+1):
            if adj[u][v] and u != v:
                adj_list[u].append(v)

    # Generate all Eulerian circuits
    circuits = []

    def dfs(u, circuit):
        # Simple DFS with backtracking
        if len(circuit) == 2*m + 1:
            circuits.append(circuit.copy())
            return

        visited = set()
        for v in adj_list[u]:
            if v not in visited:
                visited.add(v)
                circuit.append(v)
                dfs(v, circuit)
                circuit.pop()

    dfs(start, [start])

    return circuits

def is_strictly_larger(path1, path2):
    # Check if path2 is lexicographically strictly greater than path1
    for i in range(len(path1)):
        if path1[i] > path2[i]:
            return False
        if path1[i] < path2[i]:
            return True
    return False

def solve():
    data = parse_input()
    if not data:
        return

    n, m, given_path = data

    # Build graph
    adj, degrees = build_graph(given_path)

    if not has_eulerian_circuit(adj, degrees):
        print("No solution")
        return

    # Generate all Eulerian circuits
    start = given_path[0]
    circuits = generate_eulerian_circuits(adj, degrees, start)

    # Sort circuits lexicographically
    circuits.sort()

    # Find the next one that's strictly larger
    for circuit in circuits:
        if is_strictly_larger(given_path, circuit):
            print(" ".join(map(str, circuit)))
            return

    print("No solution")

if __name__ == "__main__":
    solve()
