import sys
from collections import defaultdict, deque

def parse_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None

    n = int(data[0])
    m = int(data[1])
    path = list(map(int, data[2:2+m+1]))

    return n, m, path

def build_graph(n, path):
    # Build adjacency matrix
    adj = [[0] * (n+1) for _ in range(n+1)]
    for i in range(len(path)-1):
        u = path[i]
        v = path[i+1]
        if u != v:
            adj[u][v] = 1
            adj[v][u] = 1

    return adj

def has_eulerian_circuit(adj, n):
    # Check if all vertices have even degrees
    for v in range(1, n+1):
        if adj[v][v] % 2 != 0:
            return False

    # Check if the graph is connected (excluding isolated vertices)
    visited = set()
    start = 1
    queue = deque([start])
    visited.add(start)

    while queue:
        node = queue.popleft()
        for neighbor in range(1, n+1):
            if adj[node][neighbor] and neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return True

def generate_eulerian_circuits(adj, n, m, start):
    # Generate all Eulerian circuits using Hierholzer's algorithm
    # and sort them lexicographically

    # Build adjacency lists
    adj_list = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in range(1, n+1):
            if adj[u][v] and u != v:
                adj_list[u].append(v)

    # Generate all Eulerian circuits
    circuits = []

    def dfs(u, circuit):
        # Simple DFS with backtracking
        if len(circuit) == 2*m + 1:
            circuits.append(circuit.copy())
            return

        visited = set()
        for v in adj_list[u]:
            if v not in visited:
                visited.add(v)
                circuit.append(v)
                dfs(v, circuit)
                circuit.pop()

    dfs(start, [start])

    return circuits

def is_strictly_larger(path1, path2):
    # Check if path2 is lexicographically strictly greater than path1
    for i in range(len(path1)):
        if path1[i] > path2[i]:
            return False
        if path1[i] < path2[i]:
            return True
    return False

def solve():
    data = parse_input()
    if not data:
        return

    n, m, given_path = data

    # Build adjacency matrix
    adj = build_graph(n, given_path)

    if not has_eulerian_circuit(adj, n):
        print("No solution")
        return

    # Generate all Eulerian circuits
    start = given_path[0]
    circuits = generate_eulerian_circuits(adj, n, m, start)

    # Sort circuits lexicographically
    circuits.sort()

    # Find the next one that's strictly larger
    for circuit in circuits:
        if is_strictly_larger(given_path, circuit):
