    """Check if (x, y) is a winning position in Wythoff's Game."""
    if x == y:
        return False  # Only (0, 0) is a losing position, others are winning

    a, b = (x, y) if x > y else (y, x)

    # Golden ratio: phi = (1 + sqrt(5)) / 2
    phi = (1 + math.sqrt(5)) / 2

    # If the difference is golden ratio, it's a losing position
    # Check if a == b * phi + epsilon
    k = a / phi
    k_floor = int(k)
    if abs(k_floor - k) < 1e-9:
        # Check if b == k_floor * phi + epsilon
        k2 = k_floor * phi
        if abs(k2 - b) < 1e-9:
            return False  # Losing position
