    """Check if (x, y) is a losing position (P-position) in Wythoff's Game."""
    if x == y:
        return x == 0  # Only (0, 0) is a losing position

    # Check if (x, y) is of the form (⌊kφ⌋, ⌊kφ²⌋)
    phi = (1 + math.sqrt(5)) / 2

    a, b = x, y
    if a < b:
        a, b = b, a

    # Find k such that a = b * phi (approx)
    # a should be approximately equal to b * phi
    k = a / phi
    k_floor = int(k)

    # Check if a is approximately equal to k_floor * phi
    if abs(a - k_floor * phi) < 1e-9:
        # Check if b is approximately equal to k_floor * phi^2
        if abs(b - k_floor * phi * phi) < 1e-9:
            return True

    # Check if b is approximately equal to a * phi
    k2 = b / phi
    k2_floor = int(k2)

    # Check if b is approximately equal to k2_floor * phi
    if abs(b - k2_floor * phi) < 1e-9:
        # Check if a is approximately equal to k2_floor * phi^2
        if abs(a - k2_floor * phi * phi) < 1e-9:
