import sys

def solve():
    N, K = map(int, sys.stdin.read().split())
    MOD = 998244353

    # DP[k][m]: number of ways to have m red chameleons after throwing k balls
    dp = [[0] * (N + 1) for _ in range(K + 1)]
    dp[0][0] = 1

    for k in range(K + 1):
        for m in range(N + 1):
            # From dp[k-1][m-1] by throwing a red ball to a blue chameleon
            if k > 0 and m > 0:
                dp[k][m] = (dp[k][m] + (N - (m - 1)) * dp[k - 1][m - 1]) % MOD

            # From dp[k-1][m] by throwing a red ball to a red chameleon
            if k > 0:
                dp[k][m] = (dp[k][m] + m * dp[k - 1][m]) % MOD

    print(dp[K][N])

