def solve(n):
    if n == 1:
        return 0

    # Start from (1, n) or (n, 1) and work backwards
    a, b = 1, n
    steps = 0

    while b > 1:
        if b > a:
            # We could have come from (a, b - a)
            steps += 1
            b -= a
        else:
            # We could have come from (a - b, b)
            steps += 1
            a -= b

    return steps

n = int(input())
print(solve(n))
