def generate_magical_numbers(max_length=100):
    magical_numbers = []
    for length in range(1, max_length + 1):
        for bits in range(0, 1 << length):
            binary_str = bin(bits)[2:].zfill(length)
            magical_number = ''.join(['4' if bit == '0' else '7' for bit in binary_str])
            magical_numbers.append(magical_number)
    magical_numbers.sort()
    return magical_numbers

def find_next_magical_number(N_str, magical_numbers):
    for magical_number in magical_numbers:
        if magical_number > N_str:
            return magical_number
    return None

