n, a, b = map(int, input().split())

# Find the round where a and b can meet
rounds = 1

while True:
    # For team_a, find its pair
    if a % 2 == 1:
        pair_a = (a, a + 1)
    else:
        pair_a = (a - 1, a)

    # For team_b, find its pair
    if b % 2 == 1:
        pair_b = (b, b + 1)
    else:
        pair_b = (b - 1, b)

    # If they're in the same pair, they meet
    if pair_a == pair_b:
        break

    # Advance to next round
    n //= 2
    rounds += 1

print("Final!" if rounds > 1 else rounds)
