# Function to compute cube remainder (exponents modulo 3)
def cube_remainder(n):
    factors = {}
    temp = n
    i = 2
    while i * i <= temp:
        count = 0
        while temp % i == 0:
            count += 1
            temp //= i
        factors[i] = count % 3
        i += 1
    if temp > 1:
        factors[temp] = 1 % 3
    return tuple(sorted(factors.items()))

# Count frequencies of each cube remainder
counts = {}
for num in s:
    rem = cube_remainder(num)
    if rem in counts:
        counts[rem] += 1
    else:
        counts[rem] = 1

# The maximum number of integers we can circle is at most the number of distinct cube remainders
print(len(counts))
"}

