import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    try:
        N = int(next(it))
    except StopIteration:
        return
    blue = defaultdict(int)
    for _ in range(N):
        s = next(it).strip()
        blue[s] += 1
    M = int(next(it))
    red = defaultdict(int)
    for _ in range(M):
        s = next(it).strip()
        red[s] += 1

    max_balance = 0
    seen = set()
    for s in blue:
        seen.add(s)
    for s in red:
        seen.add(s)
    for s in seen:
        balance = blue[s] - red[s]
        if balance > max_balance:
            max_balance = balance

    print(max_balance)

if __name__ == "__main__":
    solve()
"}

