import sys

def max_submatrix_sum(matrix):
    n = len(matrix)
    max_sum = float('-inf')

    # Row-wise prefix sums
    prefix_sums = [[0] * n for _ in range(n)]
    for i in range(n):
        prefix_sums[i][0] = matrix[i][0]
        for j in range(1, n):
            prefix_sums[i][j] = matrix[i][j] + prefix_sums[i][j-1]

    # 1D Kadane's algorithm
    def kadane(arr):
        max_current = max_global = arr[0]
        for i in range(1, len(arr)):
            max_current = max(arr[i], max_current + arr[i])
            max_global = max(max_global, max_current)
        return max_global

    # For each pair of rows (top, bottom), compute column-wise sums
    for top in range(n):
        for bottom in range(top, n):
            col_sums = [0] * n
            for col in range(n):
                # sum of elements from top to bottom in column col
                sum_col = 0
                for row in range(top, bottom + 1):
                    sum_col += matrix[row][col]
                col_sums[col] = sum_col
            current_max = kadane(col_sums)
            if current_max > max_sum:
                max_sum = current_max

    return max_sum

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    matrix = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(n)]
        matrix.append(row)
    result = max_submatrix_sum(matrix)
    print(result)

if __name__ == "__main__":
    solve()
"}

